use vstd::prelude::*;

verus! {

fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
    requires
        a.len() == b.len(),
    ensures
        // Output has the same length as the inputs
        result.len() == a.len(),

        // Pointwise specification: result[i] is true iff a[i] >= b[i]
        forall|i: int|
            0 <= i < a.len() ==> (result[i] <==> (a[i] >= b[i])),
{
    let n = a.len();
    let mut result: Vec<bool> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            n == a.len(),
            n == b.len(),
            result.len() == i,
            forall|j: int|
                0 <= j < i as int ==> (result[j] <==> (a[j] >= b[j])),
    {
        result.push(a[i] >= b[i]);
        i += 1;
    }

    result
}

} // verus!